import{_ as t,o,c as n,a2 as s}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Meeting mode","description":"","frontmatter":{},"headers":[],"relativePath":"guide/meeting.md","filePath":"guide/meeting.md","lastUpdated":1793721943000}'),a={name:"guide/meeting.md"};function i(r,e,h,l,d,c){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="meeting-mode" tabindex="-1">Meeting mode <a class="header-anchor" href="#meeting-mode" aria-label="Permalink to &quot;Meeting mode&quot;">​</a></h1><p>This page explains how MeetCue follows a live meeting: when it shows hints, how it handles several questions in a row, and how to read the panel.</p><h2 id="start-and-pause-listening" tabindex="-1">Start and pause listening <a class="header-anchor" href="#start-and-pause-listening" aria-label="Permalink to &quot;Start and pause listening&quot;">​</a></h2><p>Press <code>Ctrl+Alt+Space</code>, or click <strong>Start</strong> on the panel. The status dot turns green and the timer starts. Press the shortcut again to pause; nothing is sent to any provider while paused.</p><p>You can also start and pause from the tray icon menu.</p><h2 id="how-a-question-becomes-hints" tabindex="-1">How a question becomes hints <a class="header-anchor" href="#how-a-question-becomes-hints" aria-label="Permalink to &quot;How a question becomes hints&quot;">​</a></h2><ol><li><strong>Recognition</strong>: both audio sources are streamed to your speech recognition provider. Only sound that contains speech is sent; silence is skipped, apart from a short keep-alive signal.</li><li><strong>Detection</strong>: when another participant finishes a sentence, the detection model decides whether it&#39;s a question for you. Your own microphone is never checked for questions.</li><li><strong>Hints</strong>: for a question, the hint model writes three to five numbered talking points and a sample answer. Open-ended questions, such as asking for advice, your approach or a story (&quot;how do you balance work and family?&quot;), get a fuller answer with concrete practices, an example and a trade-off instead of a one-line summary. Points appear one by one as they are generated.</li></ol><p>With <strong>Early trigger</strong> on (<strong>Settings › Hints</strong>), MeetCue starts generating as soon as the speaker pauses for a moment, before the sentence is officially over. If the speaker keeps going, the hints are rewritten for the whole sentence; if the question changes noticeably, the early request is cancelled and a new one starts. This saves several hundred milliseconds on most questions.</p><p>When a speaker pauses in the middle of a question (&quot;What do you think of idea A… and idea B?&quot;), the rest is joined to the same question card and the hints are rewritten to cover both parts, instead of answering only the first half. See <a href="/meetcue/troubleshooting/quality#split">One question is split into two</a>.</p><p>With <strong>Write hints while checking the question</strong> on (also in <strong>Settings › Hints</strong>, on by default), detection and hint generation start at the same time instead of one after the other. The hints are shown only if detection confirms a question, so nothing changes on the panel, but the first point usually arrives about a second sooner. A sentence that looks like a question but isn&#39;t costs one unused hint request.</p><h2 id="read-the-panel" tabindex="-1">Read the panel <a class="header-anchor" href="#read-the-panel" aria-label="Permalink to &quot;Read the panel&quot;">​</a></h2><p>From top to bottom, the full panel shows:</p><ol><li><p><strong>Title bar</strong>: status, elapsed time, pause, keep on top, and the switch to the mini bar.</p></li><li><p><strong>Sources</strong>: a level meter for your microphone and one for system sound. They move as soon as the panel is shown, before you start, so you can check that MeetCue hears you. Nothing is sent to any provider until you start.</p></li><li><p><strong>Conversation</strong>: the newest question is shown in full at the top, with its talking points, so the panel keeps up with the meeting even when that question is still waiting its turn. Click the grey question text to see the sentences around it and why it was detected. <strong>Show full answer</strong> expands the sample answer.</p></li><li><p><strong>Question list</strong>: below it, one line per question in the order they were asked, newest first, with the time, a short summary, coverage and status. New questions appear at the top and earlier ones move down. The line of the question shown above is highlighted, and the question you are answering now is marked <strong>Now</strong>. Click a line to show that question in full in the same place above the list; its header then offers <strong>Back to the latest question</strong>, and a new question brings you back on its own.</p><p>In a long meeting the list stays short: the questions waiting their turn and the three most recent earlier ones are always shown, and older ones fold behind <strong>Show N earlier questions</strong>. <strong>Clear earlier</strong> hides every earlier question from the list for the rest of the meeting; they are still there for <code>Ctrl+Alt+[</code> and <code>Ctrl+Alt+]</code>, and <strong>Restore</strong> brings them back.</p></li><li><p><strong>Footer</strong>: shortcut reminders and the latency of the last hint.</p></li></ol><p>The <strong>mini bar</strong> (<code>Ctrl+Alt+H</code>) shows only the current question, its progress, the next point to cover in large type, and how many questions are waiting.</p><p>To keep your eyes near the camera, move the panel right under it with <code>Ctrl+Alt+Shift</code> and the arrow keys. See <a href="/meetcue/guide/shortcuts#move-the-panel">Move the panel</a>.</p><h2 id="keep-the-panel-out-of-the-way" tabindex="-1">Keep the panel out of the way <a class="header-anchor" href="#keep-the-panel-out-of-the-way" aria-label="Permalink to &quot;Keep the panel out of the way&quot;">​</a></h2><p>The panel shouldn&#39;t cover the meeting&#39;s <strong>Join</strong> button, other participants or a shared screen. Everything below works with a touchpad:</p><ul><li><strong>Drag it from anywhere.</strong> Press on any empty part of the panel, not only the title bar, and drag. A double tap and drag on a touchpad moves it too.</li><li><strong>Move</strong> in the title bar opens one-click options: <ul><li><strong>Snap to an edge or corner</strong>: eight arrows place the panel at that edge of the screen, clear of the taskbar. With more than one screen, the middle button moves it to the next screen.</li><li><strong>Saved spots</strong>: save up to three places, each with its own size and layout, and come back to them with <code>Ctrl+Alt+Shift+1</code>, <code>2</code> or <code>3</code>. See <a href="/meetcue/guide/shortcuts#saved-spots">Saved spots</a>.</li><li><strong>Size</strong>: narrow, normal or wide, and a third, half or the full height of the screen. You can also drag the panel&#39;s edges; the size is kept.</li><li><strong>Opacity</strong> and <strong>Text</strong> size, so a smaller, see-through panel stays readable.</li><li><strong>Hide for 6 seconds</strong> (<code>Ctrl+Alt+Shift+P</code>) to click something behind the panel.</li><li><strong>Let clicks pass through</strong> (<code>Ctrl+Alt+Shift+T</code>): the panel fades and the mouse reaches the window behind it. Press the shortcut again, or use the tray menu, to stop.</li></ul></li></ul><p>The font for every window, the panel&#39;s text size and opacity can also be set in <strong>Settings › General</strong>.</p><h2 id="coverage-ticks" tabindex="-1">Coverage ticks <a class="header-anchor" href="#coverage-ticks" aria-label="Permalink to &quot;Coverage ticks&quot;">​</a></h2><p>Click a point to tick it once you&#39;ve covered it, and click it again to untick it.</p><p>To have MeetCue tick points for you, turn on <strong>Settings › Hints › Tick off points as I speak</strong> (off by default). MeetCue then listens to your microphone and compares what you say with the talking points. A point you&#39;ve covered gets a green check mark, and the next uncovered point is marked <strong>Next</strong>. Points tick while you are still talking, not only when you pause. If a point is ticked wrongly or missed, click it to tick or untick it; MeetCue then leaves that point as you set it. Matching uses words for English (plurals and tenses count as the same word) and character pairs for Chinese, so paraphrasing a point closely is enough. When your wording strays further from the list, points can be ticked or missed; if that gets in your way, leave the setting off and tick points by hand.</p><p>If you use speakers instead of headphones, your microphone also hears the other participants. MeetCue ignores microphone text that closely matches what was just played, so their words don&#39;t tick off your points.</p><h2 id="several-questions-at-once" tabindex="-1">Several questions at once <a class="header-anchor" href="#several-questions-at-once" aria-label="Permalink to &quot;Several questions at once&quot;">​</a></h2><ul><li><strong>Queue interruptions</strong> (on by default): a question asked while you are answering is shown on top with its hints right away, marked <strong>Waiting</strong>, while ticks keep following the question you are answering. When you finish answering, it becomes the current question. A question still waiting when a new one comes more than two minutes later is set aside, so new questions don&#39;t pile up behind it; set-aside questions stay in the list with their hints.</li><li>A question asked while you are not speaking replaces the current one, which moves down to the earlier questions. This includes a question asked before you said anything about the previous one.</li><li>Use <code>Ctrl+Alt+[</code> and <code>Ctrl+Alt+]</code> to move between questions, and <code>Ctrl+Alt+Enter</code> to mark the current one answered.</li></ul><p>A question counts as answered only after you have spoken and then stopped, so silence before your answer never archives it.</p><h2 id="hide-the-panel-from-screen-sharing" tabindex="-1">Hide the panel from screen sharing <a class="header-anchor" href="#hide-the-panel-from-screen-sharing" aria-label="Permalink to &quot;Hide the panel from screen sharing&quot;">​</a></h2><p><strong>Hide the panel when sharing the screen</strong> is on by default. Teams, Zoom, browser screen sharing and most recording tools then capture the area behind the panel instead of the panel itself.</p><div class="warning custom-block"><p class="custom-block-title">Not a guarantee</p><p>Some recording methods and external capture hardware can still capture the panel. Test with your meeting app before relying on it.</p></div><h2 id="cost-during-a-meeting" tabindex="-1">Cost during a meeting <a class="header-anchor" href="#cost-during-a-meeting" aria-label="Permalink to &quot;Cost during a meeting&quot;">​</a></h2><p>Each call&#39;s usage is recorded and converted with the downloaded price list; calls to models without a price are counted but not costed. <strong>Settings › Providers &amp; cost</strong> shows this month&#39;s usage by provider. You can set a per-meeting and a monthly budget; MeetCue warns at 80% and, at 100%, only notifies you, pauses hints or ends the session, as you choose.</p>',31)])])}const g=t(a,[["render",i]]);export{p as __pageData,g as default};
